draw:
var g = p.gravity, v0 = p.v0, h0 = p.h0;
var tf = (v0 + Math.sqrt(v0 * v0 + 2 * g * h0)) / g;
var peak = h0 + (v0 > 0 ? (v0 * v0) / (2 * g) : 0);
var top = Math.max(peak * 1.18, 4);
var pad = 24;
var groundY = H - pad;
var sc = (groundY - pad) / top;
function Y(y) { return groundY - y * sc; }
var cx = W * 0.34;

var cyc = tf + 0.9;
var now = t % cyc;
var tt = now < tf ? now : tf;
var y = h0 + v0 * tt - 0.5 * g * tt * tt;
if (y < 0) { y = 0; }
var v = v0 - g * tt;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1;

ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(10, groundY); ctx.lineTo(W - 10, groundY); ctx.stroke();
ctx.fillStyle = C.faint;
ctx.fillText("ground, y = 0", 12, groundY + 14);

ctx.setLineDash([3, 4]);
ctx.strokeStyle = C.faint;
ctx.beginPath(); ctx.moveTo(10, Y(h0)); ctx.lineTo(W - 10, Y(h0)); ctx.stroke();
ctx.beginPath(); ctx.moveTo(10, Y(peak)); ctx.lineTo(W - 10, Y(peak)); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.faint;
ctx.fillText("release  " + h0.toFixed(0) + " m", W * 0.58, Y(h0) - 5);
ctx.fillText("peak  " + peak.toFixed(1) + " m", W * 0.58, Y(peak) - 5);

/* strobe: one dot every 0.2 s, equal time steps */
ctx.fillStyle = C.figure;
for (var s = 0; s <= tt + 1e-9; s += 0.2) {
  var ys = h0 + v0 * s - 0.5 * g * s * s;
  if (ys < 0) { continue; }
  ctx.beginPath(); ctx.arc(cx - 26, Y(ys), 2.5, 0, Math.PI * 2); ctx.fill();
}
ctx.fillStyle = C.faint;
ctx.fillText("strobe every 0.2 s", 10, pad - 8);

/* the ball */
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(cx, Y(y), 6, 0, Math.PI * 2); ctx.fill();

/* velocity arrow */
var av = v * 2.2;
if (Math.abs(av) > 60) { av = av > 0 ? 60 : -60; }
var y0p = Y(y), y1p = Y(y) - av;
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath(); ctx.moveTo(cx, y0p); ctx.lineTo(cx, y1p); ctx.stroke();
var dir = av >= 0 ? 1 : -1;
ctx.beginPath();
ctx.moveTo(cx, y1p);
ctx.lineTo(cx - 4, y1p + dir * 7);
ctx.lineTo(cx + 4, y1p + dir * 7);
ctx.closePath();
ctx.fillStyle = C.accent; ctx.fill();
ctx.fillStyle = C.ink;
ctx.fillText("v = " + v.toFixed(1) + " m/s", cx + 10, y1p + 4);

/* gravity arrow, always down, always the same length */
var gx = W - 52;
ctx.strokeStyle = C.figure; ctx.lineWidth = 2;
ctx.beginPath(); ctx.moveTo(gx, H * 0.34); ctx.lineTo(gx, H * 0.34 + 34); ctx.stroke();
ctx.beginPath();
ctx.moveTo(gx, H * 0.34 + 41);
ctx.lineTo(gx - 4, H * 0.34 + 34);
ctx.lineTo(gx + 4, H * 0.34 + 34);
ctx.closePath();
ctx.fillStyle = C.figure; ctx.fill();
ctx.fillStyle = C.ink;
ctx.fillText("a = g down", gx - 14, H * 0.34 - 6);

out.note = "t = " + tt.toFixed(2) + " s, y = " + y.toFixed(1) + " m, v = " + v.toFixed(1) +
  " m/s  |  peak " + peak.toFixed(1) + " m, lands at t = " + tf.toFixed(2) + " s";

var g = 9.8, v0 = p.v0;
var tf = 2 * v0 / g;
var tp = v0 / g;
var hmax = v0 * v0 / (2 * g);
var pad = 34;
var colW = (W - pad * 2 - 24) / 3;
var gh = H - pad - 26;
var top = pad;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1;

function axes(x0, title) {
  ctx.strokeStyle = C.rule;
  ctx.beginPath();
  ctx.moveTo(x0, top);
  ctx.lineTo(x0, top + gh);
  ctx.lineTo(x0 + colW, top + gh);
  ctx.stroke();
  ctx.fillStyle = C.ink;
  ctx.fillText(title, x0, top - 10);
  ctx.fillStyle = C.faint;
  ctx.fillText("t", x0 + colW - 6, top + gh + 15);
}

/* panel 1: height against time */
var x1 = pad;
axes(x1, "y (m)");
ctx.strokeStyle = C.accent; ctx.lineWidth = 2;
ctx.beginPath();
for (var i = 0; i <= 120; i++) {
  var s = tf * i / 120;
  var y = v0 * s - 0.5 * g * s * s;
  var px = x1 + colW * s / tf;
  var py = top + gh - (gh - 10) * y / hmax;
  i === 0 ? ctx.moveTo(px, py) : ctx.lineTo(px, py);
}
ctx.stroke();
ctx.setLineDash([3, 4]); ctx.strokeStyle = C.faint; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(x1, top + 10); ctx.lineTo(x1 + colW / 2, top + 10); ctx.stroke();
ctx.beginPath(); ctx.moveTo(x1 + colW / 2, top + 10); ctx.lineTo(x1 + colW / 2, top + gh); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.faint;
ctx.fillText(hmax.toFixed(1), x1 - 30, top + 14);
ctx.fillText(tp.toFixed(2) + " s", x1 + colW / 2 - 12, top + gh + 15);

/* panel 2: velocity against time */
var x2 = pad + colW + 12;
axes(x2, "v (m/s)");
var mid = top + gh / 2;
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(x2, mid); ctx.lineTo(x2 + colW, mid); ctx.stroke();
ctx.strokeStyle = C.accent; ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(x2, mid - (gh / 2 - 8));
ctx.lineTo(x2 + colW, mid + (gh / 2 - 8));
ctx.stroke();
ctx.fillStyle = C.faint;
ctx.fillText("+" + v0.toFixed(0), x2 - 26, mid - gh / 2 + 12);
ctx.fillText("-" + v0.toFixed(0), x2 - 26, mid + gh / 2 - 2);
ctx.fillText("slope = -g", x2 + 6, mid - 8);

/* panel 3: acceleration against time */
var x3 = pad + 2 * colW + 24;
axes(x3, "a (m/s^2)");
var mid3 = top + gh / 2;
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(x3, mid3); ctx.lineTo(x3 + colW, mid3); ctx.stroke();
ctx.strokeStyle = C.accent; ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(x3, mid3 + gh * 0.22);
ctx.lineTo(x3 + colW, mid3 + gh * 0.22);
ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("-9.8, flat", x3 + 6, mid3 + gh * 0.22 - 7);

/* moving cursor tying the three panels together */
var now = t % tf;
ctx.strokeStyle = C.figure; ctx.lineWidth = 1;
ctx.setLineDash([2, 3]);
var cols = [x1, x2, x3];
for (var k = 0; k < 3; k++) {
  var cxk = cols[k] + colW * now / tf;
  ctx.beginPath(); ctx.moveTo(cxk, top); ctx.lineTo(cxk, top + gh); ctx.stroke();
}
ctx.setLineDash([]);

var yc = v0 * now - 0.5 * g * now * now;
var vc = v0 - g * now;
out.note = "t = " + now.toFixed(2) + " s: y = " + yc.toFixed(1) + " m, v = " + vc.toFixed(1) +
  " m/s, a = -9.80 m/s^2 the whole way";

var g = 9.8, Hh = p.height, u = p.u;
var tm = Hh / u;
var tland = Math.sqrt(2 * Hh / g);
var ymeet = Hh - 0.5 * g * tm * tm;
var pad = 26;
var groundY = H - pad;
var sc = (groundY - pad) / (Hh * 1.05);
function Y(y) { return groundY - y * sc; }
var xa = W * 0.34, xb = W * 0.56;

var stop = tm < tland ? tm : tland;
var cyc = stop + 1.0;
var now = t % cyc;
var tt = now < stop ? now : stop;

var yA = Hh - 0.5 * g * tt * tt;
var yB = u * tt - 0.5 * g * tt * tt;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1;
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(10, groundY); ctx.lineTo(W - 10, groundY); ctx.stroke();

ctx.setLineDash([3, 4]); ctx.strokeStyle = C.faint;
ctx.beginPath(); ctx.moveTo(10, Y(Hh)); ctx.lineTo(W - 10, Y(Hh)); ctx.stroke();
if (ymeet > 0) {
  ctx.beginPath(); ctx.moveTo(10, Y(ymeet)); ctx.lineTo(W - 10, Y(ymeet)); ctx.stroke();
}
ctx.setLineDash([]);
ctx.fillStyle = C.faint;
ctx.fillText("drop from " + Hh.toFixed(0) + " m", 12, Y(Hh) - 6);
if (ymeet > 0) { ctx.fillText("they meet at " + ymeet.toFixed(1) + " m", 12, Y(ymeet) - 6); }

/* gap bar: the separation closes at the constant rate u */
ctx.strokeStyle = C.figure; ctx.lineWidth = 2;
ctx.beginPath(); ctx.moveTo(W - 34, Y(yA)); ctx.lineTo(W - 34, Y(yB)); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText((yA - yB).toFixed(1) + " m apart", W - 120, (Y(yA) + Y(yB)) / 2 - 6);

ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(xa, Y(yA), 6, 0, Math.PI * 2); ctx.fill();
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(xb, Y(yB > 0 ? yB : 0), 6, 0, Math.PI * 2); ctx.fill();
ctx.fillStyle = C.ink;
ctx.fillText("dropped", xa - 24, Y(yA) - 12);
ctx.fillText("thrown up at " + u.toFixed(0) + " m/s", xb + 12, Y(yB > 0 ? yB : 0) + 4);

out.note = "gap = " + Hh.toFixed(0) + " - " + u.toFixed(0) + "t, so they meet at t = " +
  tm.toFixed(2) + " s and height " + (ymeet > 0 ? ymeet.toFixed(1) + " m" : "ground level or below");

var g = 9.8, vt = p.vt;
var tmax = 4 * vt / g;
var pad = 38;
var gw = W - pad - 16, gh = H - pad - 26;
var x0 = pad, y0 = 20;
var vmax = vt * 1.45;
function X(s) { return x0 + gw * s / tmax; }
function V(v) { return y0 + gh - gh * v / vmax; }

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1;
ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.moveTo(x0, y0); ctx.lineTo(x0, y0 + gh); ctx.lineTo(x0 + gw, y0 + gh);
ctx.stroke();
ctx.fillStyle = C.faint;
ctx.fillText("v (m/s)", x0 - 30, y0 + 4);
ctx.fillText("t (s)", x0 + gw - 18, y0 + gh + 16);
ctx.fillText("0", x0 - 12, y0 + gh + 4);
ctx.fillText(tmax.toFixed(1), x0 + gw - 10, y0 + gh + 16);

/* terminal speed line */
ctx.setLineDash([4, 5]); ctx.strokeStyle = C.faint;
ctx.beginPath(); ctx.moveTo(x0, V(vt)); ctx.lineTo(x0 + gw, V(vt)); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.ink;
ctx.fillText("terminal speed " + vt.toFixed(1) + " m/s", x0 + 8, V(vt) - 6);

/* no-drag line v = gt */
ctx.strokeStyle = C.figure; ctx.lineWidth = 1.5;
ctx.beginPath();
ctx.moveTo(X(0), V(0));
var send = vmax / g < tmax ? vmax / g : tmax;
ctx.lineTo(X(send), V(g * send));
ctx.stroke();
ctx.fillStyle = C.figure;
ctx.fillText("no drag: v = gt", X(send) + 4, V(g * send) + 14);

/* with drag */
ctx.strokeStyle = C.accent; ctx.lineWidth = 2;
ctx.beginPath();
for (var i = 0; i <= 160; i++) {
  var s = tmax * i / 160;
  var v = vt * (1 - Math.exp(-g * s / vt));
  i === 0 ? ctx.moveTo(X(s), V(v)) : ctx.lineTo(X(s), V(v));
}
ctx.stroke();

/* time constant marker */
var tau = vt / g;
ctx.setLineDash([2, 3]); ctx.strokeStyle = C.faint; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(X(tau), y0 + gh); ctx.lineTo(X(tau), V(0.632 * vt)); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.faint;
ctx.fillText("t = vt/g", X(tau) - 16, y0 + gh + 16);

/* sweeping cursor */
var now = t % tmax;
var vnow = vt * (1 - Math.exp(-g * now / vt));
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(X(now), V(vnow), 5, 0, Math.PI * 2); ctx.fill();
ctx.strokeStyle = C.figure; ctx.lineWidth = 1;
ctx.setLineDash([2, 3]);
ctx.beginPath(); ctx.moveTo(X(now), V(vnow)); ctx.lineTo(x0, V(vnow)); ctx.stroke();
ctx.setLineDash([]);

out.note = "t = " + now.toFixed(2) + " s: with drag v = " + vnow.toFixed(2) +
  " m/s (" + (100 * vnow / vt).toFixed(0) + "% of terminal), without drag v = " +
  (g * now).toFixed(1) + " m/s";
